//! Completed whole/prefix FIX delivery over the same bounded report framing.
use super::*;use dq_analyze::native_fix_wire::{Schema,Terminal as FixTerminal,Scope,Mode};
#[derive(Debug)]struct FixDeliveryFailure{committed_files:usize,primary:io::Error}
impl std::fmt::Display for FixDeliveryFailure{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"native authored FIX {} file(s) committed; delivery failed: {}",self.committed_files,self.primary)}}impl Error for FixDeliveryFailure{fn source(&self)->Option<&(dyn Error+'static)>{Some(&self.primary)}}
fn delivery(error:io::Error,committed_files:usize)->io::Error{io::Error::new(error.kind(),FixDeliveryFailure{committed_files,primary:error})}
pub(crate) fn send_fix(stream:&mut impl Write,staged:crate::native_fix::StagedBatch,work:&dyn SourceArenaWork)->Result<(),SendFailure>{
 let crate::native_fix::StagedBatch{root,prefixes,mode,apply,completed,diagnostics,report,_credit}=staged;let committed_files=completed.committed_files;let inputs=completed.inputs;
 let convert=|error:Box<dyn Error>|match error.downcast::<io::Error>(){Ok(actual)=>*actual,Err(other)=>io::Error::other(other.to_string())};inputs.require_current().map_err(convert).map_err(|error|SendFailure::BeforePublication(delivery(error,committed_files)))?;
 let count=|n:usize|u64::try_from(n).map_err(|_|SendFailure::BeforePublication(delivery(io::ErrorKind::OutOfMemory.into(),committed_files)));
 let terminal=FixTerminal{schema:Schema::V1,complete:true,full_policy_parity:false,root,scope:if prefixes.is_empty(){Scope::AllTrackedSources}else{Scope::PathPrefixes},prefixes,mode,apply,frame:completed.frame,selected:count(completed.selected)?,visited:count(completed.visited)?,rewrites:count(completed.rewrites)?,residue:count(completed.residue)?,committed_files:count(committed_files)?,diagnostics:diagnostics.as_ref().map(seal_of),report:seal_of(&report)};
 terminal.require(&terminal.root,&terminal.prefixes,mode,apply).map_err(|error|SendFailure::BeforePublication(delivery(error,committed_files)))?;encode_header(&terminal).map_err(|error|SendFailure::BeforePublication(delivery(error,committed_files)))?;let _scratch=work.reserve(SEND_SCRATCH).map_err(|error|SendFailure::BeforePublication(delivery(error,committed_files)))?;
 let result=(||{control::checkpoint()?;if let Some(stage)=diagnostics{stage.publish(&mut FragmentWriter{stream:&mut *stream,channel:Channel::Diagnostics,sequence:0,offset:0})?;}report.publish(&mut FragmentWriter{stream:&mut *stream,channel:Channel::Report,sequence:0,offset:0})?;inputs.require_current().map_err(convert)?;control::checkpoint()?;protocol::send(stream,&SendReply::NativeFixFinished(terminal))})();result.map_err(|error|SendFailure::AfterPublication(delivery(error,committed_files)))
}
pub(crate) struct DeliveredFix{terminal:FixTerminal,diagnostics:Option<Verified>,report:Verified}
impl DeliveredFix{pub(crate)fn publish(self,output:&mut impl Write)->io::Result<()>{let committed=usize::try_from(self.terminal.committed_files).map_err(|_|invalid("native FIX commit count overflow"))?;let result=(||{let(header,length)=encode_header(&self.terminal)?;output.write_all(&header[..length])?;if let Some(stage)=self.diagnostics{stage.publish(output)?;}self.report.publish(output)})();result.map_err(|error|delivery(error,committed))}}
pub(crate)fn receive_fix(stream:&mut impl Read,cache:&Path,root:&Path,prefixes:&[String],mode:Mode,apply:bool)->Result<DeliveredFix,Box<dyn Error>>{
 let(mut accepted,mut diagnostics,mut report)=(false,Collector::default(),Collector::default());loop{control::checkpoint()?;match protocol::receive_bounded::<ReceiveReply>(stream,protocol::MAX_FRAME)?{
  ReceiveReply::Accepted if !accepted=>accepted=true,ReceiveReply::Rejected(error)if diagnostics.next==0&&report.next==0=>return Err(RequestFailure{kind:error.kind,message:error.message}.into()),
  ReceiveReply::SelectedReportFragment(fragment)if accepted=>match fragment.channel{Channel::Diagnostics=>diagnostics.push(cache,&fragment)?,Channel::Report=>report.push(cache,&fragment)?,_=>return Err(invalid("native FIX received unrelated report channel").into())},
  ReceiveReply::NativeFixFinished(terminal)if accepted=>{terminal.require(root,prefixes,mode,apply)?;require_end(stream)?;let diagnostics=diagnostics.finish(terminal.diagnostics)?;let report=report.finish(Some(terminal.report))?.ok_or_else(||invalid("native FIX terminal lacks actual report"))?;return Ok(DeliveredFix{terminal,diagnostics,report})},_=>return Err(invalid("unexpected native FIX transport frame").into()),
 }}}

#[cfg(test)]mod controls{use super::*;
 #[test]fn actual_validated_fix_spool_delivery_keeps_first_output_io_and_verified_commit_status(){
 let cache=crate::test_scratch::dir("native-fix-delivered-output");let mut stage=crate::selected_report_spool::Stage::new(&cache).unwrap();stage.write_all(b"1 rewrite(s) applied, 0 for hand conversion\n").unwrap();let report=stage.seal().unwrap().validate(|r|{let mut bytes=[0u8;8192];loop{control::checkpoint()?;if r.read(&mut bytes)?==0{return Ok(())}}}).unwrap().0;let root=std::fs::canonicalize(&cache).unwrap();let terminal=FixTerminal{schema:Schema::V1,complete:true,full_policy_parity:false,root,scope:Scope::AllTrackedSources,prefixes:Vec::new(),mode:Mode::Tracked,apply:true,frame:dq_analyze::selected_exclusions_wire::Frame{semantic_revision:Hex128(1),source_revision:Hex128(2),policy_revision:Hex128(3)},selected:3,visited:3,rewrites:1,residue:0,committed_files:1,diagnostics:None,report:seal_of(&report)};terminal.require(&terminal.root,&[],Mode::Tracked,true).unwrap();struct Stop;impl Write for Stop{fn write(&mut self,_:&[u8])->io::Result<usize>{Err(io::Error::from_raw_os_error(1450))}fn flush(&mut self)->io::Result<()>{Ok(())}}let error=DeliveredFix{terminal,diagnostics:None,report}.publish(&mut Stop).unwrap_err();let actual=error.get_ref().unwrap().downcast_ref::<FixDeliveryFailure>().unwrap();assert_eq!(actual.committed_files,1);assert_eq!(actual.primary.raw_os_error(),Some(1450));
 }
}
